import{_ as l,o as a,c as r,a2 as i}from"./chunks/framework.CAKCj7G0.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"Java/Spring/MVC.md","filePath":"Java/Spring/MVC.md","lastUpdated":1760888831000}'),t={name:"Java/Spring/MVC.md"};function d(n,e,o,p,s,V){return a(),r("div",null,[...e[0]||(e[0]=[i('<h2 id="_46-1-mvcmvc" tabindex="-1">46.1. MVCMVC <a class="header-anchor" href="#_46-1-mvcmvc" aria-label="Permalink to &quot;46.1. MVCMVC&quot;">​</a></h2><ul><li>基于 Java 实现的 MVC 架构模式的轻量级框架</li><li>web 软件的一种设计模式，软件被分为 Model（模型）、View（视图）、Controller（控制器） Model：对象模型，封装数据与对数据的相关操作 View：代表用户界面 Controller：负责视图和模型之间的交互,控制对用户输入的响应、响应方式和流</li><li>服务端代码分层：表现层、业务层、数据访问层</li><li>经典 MVC：jsp + servlet + javabean</li><li>优点：降低软件系统耦合性</li><li>执行流程 用户发起 Http request 请求，请求被提交到 DispatcherServlet DispatcherServlet 请求 HandlerMapping，返回执行器 DispatcherServlet 将 Handler 信息发送给 HandlerAdapter HandlerAdapter 根据 Handler 信息执行对应的 Handler（Controller） Handler 执行后返回 ModelAndView（Spring MVC 对象，包括 Model、View 信息） 给 HandlerAdapter HandlerAdapter 将 ModelAndView 返回给 DispatcherServlet DispatcherServlet 通过 ViewResolver 对 ModelAndView 进行解析 VIewResolver 将试图结果返回给 DispatchServlet DispatcherServlet 进行视图渲染，数据填充，生成 View View 返回到浏览器</li><li>DispatcherServlet（前端控制器） 所有请求都要经过 DispatcherServlet 统一分发。相当于一个转发器或中央处理器,控制整个流程的执行,对各个组件进行统一调度,降低组件之间的耦合性。</li><li>HandlerMapping（Handler 映射器） 是根据请求的 URL 路径,通过注解或者 XML 配置,寻找匹配的处理器（Handler）信息。</li><li>HandlerAdapter（Handler 适配器） 根据映射器找到的处理器（Handler）信息,按照特定规则执行相关的处理器（Handler）</li><li>Handler（处理器） 执行相关的请求处理逻辑,并返回相应的数据和视图信息,将其封装至 ModelAndView 对象中</li><li>VIewResolver（视图解析器） 视图解析器,其作用是进行解析操作,通过 ModelAndView 对象中的 View 信息将逻辑视图名解析成真正的视图 View</li></ul>',2)])])}const _=l(t,[["render",d]]);export{v as __pageData,_ as default};
